import json,re,subprocess,sys
for rev in sys.argv[1:]:
 q=subprocess.check_output(['git','show',rev+':corpus/QUALITY.md'],text=True); blocks=re.findall(r'(?ms)^([0-9]+)\. (.*?)(?=^[0-9]+\. |\Z)',q); literal=sum(bool(re.search(r'^'+n+r'\. .*lessons/',q,re.M)) for n,b in blocks); semantic=sum('lessons/' in b for n,b in blocks); print(json.dumps({'revision':rev,'total':len(blocks),'literal':literal,'semantic_block':semantic,'literal_score':10*literal/len(blocks),'semantic_block_score':10*semantic/len(blocks)}))
